const difficulties = ['easy', 'easy-medium', 'medium', 'hard'];

function generateQuestions(subject) {
  const questions = [];
  const usedPrompts = new Set();

  for (let i = 1; i <= 200; i++) {
    const topic = subject.topics[(i - 1) % subject.topics.length];
    const difficulty = difficulties[Math.floor((i - 1) / 50) % difficulties.length];
    const id = `${subject.prefix}-${String(i).padStart(3, '0')}`;
    const variant = Math.floor((i - 1) / subject.topics.length);

    let q = getQuestion(subject.name, topic, variant, i);
    let prompt = q.prompt;

    if (usedPrompts.has(prompt)) {
      prompt = `${prompt} [Variant ${variant + 1}]`;
    }
    usedPrompts.add(prompt);

    questions.push({
      id,
      category: 'frontend',
      subcategory: subject.name,
      topic,
      questionType: 'mcq',
      difficulty,
      prompt,
      options: q.options,
      correctAnswer: q.correctAnswer,
      explanation: q.explanation,
      expectedTimeSeconds: 30 + (difficulty === 'hard' ? 30 : difficulty === 'medium' ? 15 : 0),
      points: difficulty === 'hard' ? 15 : difficulty === 'medium' ? 10 : 5,
      tags: [subject.name.toLowerCase(), topic.toLowerCase().replace(/\s+/g, '-')],
      verificationStatus: 'verified'
    });
  }
  return questions;
}

function getQuestion(subject, topic, variant, index) {
  const generators = {
    'ReactJS': genReact,
    'TypeScript': genTS,
    'JavaScript': genJS,
    'HTML': genHTML,
    'CSS': genCSS,
    'ES6': genES6,
    'Redux': genRedux,
    'jQuery': genJQuery
  };
  return generators[subject](topic, variant, index);
}

